describe('Modal Form Submission', () => {
    beforeEach(() => {
        cy.visit('/'); // Adjust the URL to your application
        cy.get('.open-modal-button').click(); // Adjust selector to open the modal
    });

    it('should submit the form successfully and display success feedback', () => {
        cy.get('input[name="username"]').type('testuser');
        cy.get('input[name="email"]').type('testuser@example.com');
        cy.get('textarea[name="message"]').type('This is a test message.');
        cy.get('.submit-button').click(); // Adjust selector for the submit button

        cy.get('.success-message').should('be.visible').and('contain', 'Form submitted successfully!');
    });

    it('should show an error message when submitting the form with empty fields', () => {
        cy.get('.submit-button').click(); // Attempt to submit without filling the form

        cy.get('.error-message').should('be.visible').and('contain', 'Please fill out this field.');
    });
});
